from collections import deque

n = 23
edges = [(i, (i+1) % n) for i in range(n)]  # cycle of 23
chords = [(0,5), (5,10), (10,15), (15,20), (2,20)]
# Check these are well spaced
edges.extend(chords)

adj = {i: set() for i in range(n)}
for u,v in edges:
    adj[u].add(v); adj[v].add(u)

def girth(adj, n):
    g = float('inf')
    for s in range(n):
        dist = {s: 0}
        parent = {s: -1}
        q = deque([s])
        while q:
            u = q.popleft()
            for w in adj[u]:
                if w not in dist:
                    dist[w] = dist[u]+1
                    parent[w] = u
                    q.append(w)
                elif parent[u] != w:
                    cl = dist[u]+dist[w]+1
                    if cl < g: g = cl
    return g

print("edges:", len(edges), "girth:", girth(adj, n))

# 4-color via backtracking
def color(adj, n, k=4):
    col = [-1]*n
    order = sorted(range(n), key=lambda x: -len(adj[x]))
    def bt(i):
        if i == n: return True
        v = order[i]
        used = {col[u] for u in adj[v] if col[u]!=-1}
        for c in range(k):
            if c not in used:
                col[v] = c
                if bt(i+1): return True
                col[v] = -1
        return False
    if bt(0): return col
    return None

c = color(adj, n, 4)
print("coloring:", c)
print("edges list:", edges)
